import styles from "./styles.module.scss";
import { RawEmbed } from "@/chat-api/RawData";
import Icon from "@/components/ui/icon/Icon";
import { createSignal, JSX, Show } from "solid-js";

const THUMBNAIL_FALLBACKS = ["sddefault", "hqdefault", "mqdefault"];

function applyThumbnailFallback(el: HTMLImageElement, code: string, index = 0) {
  el.onload = () => {
    if (el.naturalWidth === 120 && el.naturalHeight === 90) {
      applyThumbnailFallback(el, code, index + 1);
    }
  };
  el.src = `https://i.ytimg.com/vi/${code}/${THUMBNAIL_FALLBACKS[index]}.jpg`;
}

export const RawYoutubeEmbed = (props: {
  code: string;
  embed: RawEmbed;
  shorts: boolean;
  style?: JSX.CSSProperties;
}) => {
  const [playVideo, setPlayVideo] = createSignal<boolean>(false);

  return (
    <div class={styles.youtubeEmbed}>
      <div class={styles.video} style={props.style}>
        <Show when={!playVideo()}>
          <img
            style={{ width: "100%", height: "100%", "object-fit": "cover" }}
            ref={(el) => applyThumbnailFallback(el, props.code)}
          />
          <div
            onClick={(event) => {
              event.stopPropagation();
              event.preventDefault();
              setPlayVideo(!playVideo());
            }}
            class={styles.playButtonContainer}
          >
            <div class={styles.playButton}>
              <Icon name="play_arrow" size={28} />
            </div>
          </div>
        </Show>
        <Show when={playVideo()}>
          <iframe
            width="100%"
            height="100%"
            src={`https://www.youtube-nocookie.com/embed/${props.code}?autoplay=1`}
            frameborder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            allowfullscreen
          />
        </Show>
      </div>
      <div class={styles.youtubeEmbedDetails}>
        <div class={styles.title}>{props.embed.title}</div>
        <div class={styles.info}>
          {props.embed.channelName} •{" "}
          <span class={styles.date}>{props.embed.uploadDate}</span>
        </div>
        <div class={styles.description}>{props.embed.description}</div>
      </div>
    </div>
  );
};
